  "Look through its eyes": "Посмотри его глазами",
  "Look through the perception field of any being — pet, tree, whale, moss.": "Посмотри через поле восприятия любого существа — питомца, дерева, кита, мха.",
  "Loom the rewrite": "Сплести переписывание",
