  "Maps the senescent cells hiding in a tissue and designs their cleared exit.": "Картирует стареющие клетки, скрывающиеся в ткани, и проектирует их очищенный выход.",
  "Maps where the visible world hardens out of the quantum foam.": "Картирует, где видимый мир затвердевает из квантовой пены.",
  "Metaphysical · mystique — omens, symbols and the invisible breathing through the tale": "Метафизическое · мистическое — знамения, символы и невидимое, дышащее сквозь повествование",
