  "Radical longevity, senolytics and the pathways that reverse aging; organs printed in three dimensions and organoids living on chips; autonomous therapeutic nanorobotics — and the translation of all of it into the living clinic.": "Радикальное долголетие, сенолитики и пути, обращающие старение; органы, напечатанные в трёх измерениях, и органоиды, живущие на чипах; автономная терапевтическая нанороботика — и перевод всего этого в живую клинику.",
  "Read again": "Прочитать снова",
  "Read the whole novel": "Прочитать весь роман",
  "Read them aloud, slowly. They are not decorations — they are the blueprint of the intervention, and every term is a place where you can lean.": "Читайте их вслух, медленно. Это не украшения — это чертёж вмешательства, и каждый термин — это место, на которое можно опереться.",
  "Read them aloud, slowly. They are not decorations — they are the lyrics of the mechanism, and every term is a place where you can lean.": "Читайте их вслух, медленно. Это не украшения — это слова механизма, и каждый термин — место, на которое можно опереться.",
  "Reading the body's wire": "Чтение проволоки тела",
  "Reading the frequencies": "Чтение частот",
