  "Reading your own line": "Чтение вашей собственной линии",
  "Reads a tumor's mutations as a patient-specific antigen cast for the immune system.": "Читает мутации опухоли как антиген, специфичный для пациента, предназначенный для иммунной системы.",
  "Reads how an experience is written into cellular and neural memory.": "Читает, как опыт записан в клеточную и нейронную память.",
  "Reads the echo of an outcome that leaned back to arrange its own arrival.": "Читит эхо исхода, который отступил, чтобы устроить собственное прибытие.",
  "Reads the methylation clock of a life and designs the safe rewinding of its marks.": "Читает метилированные часы жизни и проектирует безопасную перемотку их меток.",
  "Reads the plenum under empty space and what it remembers.": "Читит полноту под пустым пространством и что оно помнит.",
  "Reads the standing field a living being holds and hums.": "Читит стоячее поле, которое живое существо держит и по которому гудит.",
  "Reads the tide of likeliness beneath an event before it arrives.": "Читит прилив вероятности под событием до его прихода.",
  "Reality Formulas": "Формулы Реальности",
  "Receiving the transmission…": "Передача принимается…",
  "Recodes a genome's vocabulary for safety, production or new chemistry.": "Перекодирует словарь генома для безопасности, производства или новой химии.",
  "Reflect": "Отразить",
  "Resonance": "Резонанс",
  "Rest a breath, then try again — the email door always serves.": "Передохни, а затем попробуй снова — email-дверь всегда помогает.",
  "Rest a breath, then try the Google door again.": "Передохни, а затем попробуй дверь Google снова.",
