  "Show me how a belief becomes a wall, and how it becomes a door.": "Покажи мне, как вера становится стеной, и как она становится дверью.",
  "Show the window's notes": "Показать заметки окна",
  "Shows how two chosen things are woven at one seam, and what one does to the other.": "Показывает, как две выбранные вещи сотканы в одном шве, и что одна делает с другой.",
