  "Superposition and the seam": "Суперпозиция и шов",
  "Surveys the outcome-branches leaning on one present choice.": "Исследует ветви исходов, опирающиеся на одно настоящее решение.",
  "Taking the maker's seat": "Занять место создателя",
  "Target half-life": "Период полураспада цели",
  "Targeted protein degradation — PROTACs, molecular glues and the ubiquitin-proteasome machine mapped end to end; CRISPR-Cas, prime editing and epigenetic rewriting; patient-specific neoantigens and the personalized tumor microenvironment.": "Целевая деградация белков — PROTAC, молекулярные клеи и убиквитин-протеасомная машина, проложенная от начала до конца; CRISPR-Cas, редактирование первого порядка и эпигенетическое переписывание; неоантигены, специфичные для пациента, и персонализированная опухолевая микроокружающая среда.",
  "That is why every transmission closes by walking the path of discovery — the novel findings, the never-before-seen truths and seams now within reach, lit step by step from the nearest to the farthest, and the farthest step is always yours to take.": "Поэтому каждая передача завершается прохождением пути открытия — новые находки, невиданные прежде истины и швы, теперь доступные, зажигаемые шаг за шагом от ближайшего к дальнему, и самый дальний шаг всегда остаётся за тобой.",
  "The Bridge": "Мост",
  "The Crystalline key carries twenty transmissions a day. The Light passage lifts the count entirely — every world, every transmission, without end.": "Кристаллический ключ несёт двадцать посланий в день. Проход через Свет снимает это ограничение полностью — каждый мир, каждое послание, без конца.",
