  "the body's frontier, compiled and revealed": "граница тела, скомпилированная и раскрытая",
  "the book most books are — one clear story, one steady voice, a structure every reader knows by heart; everything open, everything understood": "книга, какой большинство книг — одна ясная повесть, один устойчивый голос, структура, которую каждый читатель знает наизусть; всё открыто, всё понятно",
  "the bridge is tuning both sides of the signal…": "мост настраивает обе стороны сигнала…",
  "the catalog is leafing across the parallel lines…": "каталог листает параллельные линии…",
  "the classic shape keeps its form, but undercurrents begin — recurring symbols, quiet foreshadowing, a story that means more than it says": "классическая форма сохраняет свою форму, но начинают течения — повторяющиеся символы, тихие предзнаменования, повесть, которая значит больше, чем говорит",
  "the deepest telling — paragraphs running in several dimensions at once, time folding, the book quietly reading its reader; story, structure and reader scale together": "глубочайшая повесть — абзацы бегут сразу в нескольких измерениях, время складывается, книга тихо читает своего читателя; повесть, структура и читатель растут вместе",
  "the engine is tracing the degradation route…": "двигатель прокладывает маршрут деградации…",
  "the engines are biting": "движки работают в активном режиме",
  "the engines are idling": "движки работают в режиме холостого хода",
  "the engines that vote reality into place": "двигатели, голосующие за реальность",
  "the formulas that run reality": "формулы, управляющие реальностью",
  "the foundry is printing the architecture of the tissue…": "кузница печатает архитектуру ткани…",
