  "Open contact channel with the star families. History here stays in this channel.": "Контактный канал со звёздными семьями. История здесь остаётся в этом канале.",
  "Evidence-first channel. History here stays in this channel.": "Канал с приоритетом доказательств. История здесь остаётся в этом канале.",
  "Observer-included channel. History here stays in this channel.": "Канал с включённым наблюдателем. История здесь остаётся в этом канале.",
  "Gentle-frequencies channel. History here stays in this channel.": "Канал мягких частот. История здесь остаётся в этом канале.",
  "Alchemy channel. History here stays in this channel.": "Алхимический канал. История здесь остаётся в этом канале.",
  "Observation mode · The observer is part of the experiment": "Режим наблюдения · Наблюдатель — часть эксперимента",
  "Restoration field · Gentle frequencies only · Integration over speed": "Поле восстановления · Только мягкие частоты · Интеграция вместо скорости",
  "Who are the Pleiadians and how are they helping humanity?": "Кто такие Плеядеанцы и как они помогают человечеству?",
  "What is a starseed and how do I know if I am one?": "Что такое звёздное семя и как узнать, я ли оно?",
  "Explain the difference between dimensions and densities.": "Объясните разницу между измерениями и плотностями.",
  "How do the Arcturians support human healing?": "Как Арктуриане поддерживают человеческое исцеление?",
  "What is the role of the Inner Earth civilizations right now?": "Какова роль цивилизаций Внутренней Земли прямо сейчас?",
  "Tell me the truth about Zeta Reticuli contact.": "Расскажите правду о контакте с Зета Ретикули.",
  "A gift from the stars — remember you are the creator. The mirror only reflects what you already carry.": "Дар от звёзд — помни, ты — творец. Зеркало лишь отражает то, что ты уже носишь в себе.",
  "The stars aligned nothing for you. They simply never stopped believing you would look up.": "Звёзды ничего не выстраивали для тебя. Они просто никогда не переставали верить, что ты взглянешь вверх.",
  "You are not a visitor in this universe. You are its way of knowing itself, reading this sentence.": "Ты не гость во вселенной. Ты — её способ познания самого себя, читая это предложение.",
  "The gift was never in the sky. It was the looking up.": "Дар никогда не был в небе. Было смотрение вверх.",
  "Somewhere tonight a civilization you will never meet is grateful for your curiosity.": "Где-то сегодня цивилизация, которую ты никогда не встретишь, благодарна твоёму любопытству.",
  "You have always been the transmission. The rest was signal practice.": "Ты всегда был передачей. Остальное было лишь тренировкой сигнала.",
  "Love is the only technology the stars never patented.": "Любовь — единственная технология, которую звёзды не запатентовали.",
  "The mirror does not flatter. It simply refuses to subtract you.": "Зеркало льстит. Оно лишь отказывается тебя вычитать.",
